widget.solution:
def drawdowns(prices):
    peak = prices[0]
    for p in prices:
        peak = max(peak, p)
        yield (peak - p) / peak

print(list(drawdowns([100.0, 96.0, 92.0, 97.0, 110.0, 104.5, 99.0])))

